use vstd::prelude::*;

verus! {

    // splitlines: for each input string, produce a non-empty list of strings,
    // preserving the outer list length.
    //
    // Here we give a trivial implementation: each input string becomes
    // a singleton list containing that string.  This satisfies:
    //   1) output.len() == input.len()
    //   2) each inner Vec<String> has length 1 > 0
    //
    // The `keepends` flag is ignored in this simple implementation.
    fn splitlines(a: Vec<String>, keepends: bool) -> (res: Vec<Vec<String>>)
        requires
            // Input list must be non-empty
            a.len() > 0,
        ensures
            // The outer list length is preserved
            res.len() == a.len(),
        ensures
            // Every inner list is non-empty
            forall |i: int|
                0 <= i && i < res.len() ==>
                res[i as usize].len() > 0,
    {
        // Allocate result with the same capacity as the input
        let mut res: Vec<Vec<String>> = Vec::with_capacity(a.len());
        let mut idx: usize = 0;
        // Iterate over each element of `a`
        while idx < a.len()
            invariant
                // iteration index is in bounds
                idx <= a.len(),
                // we have pushed exactly `idx` elements so far
                res.len() == idx,
                // each pushed inner list is non-empty
                forall |j: int| 0 <= j && j < idx ==>
                    res[j as usize].len() > 0,
            decreases
                a.len() - idx,
        {
            // Clone the string at position idx
            let s: String = a[idx].clone();
            // Wrap it into a singleton list
            let inner: Vec<String> = vec![s];
            // This inner Vec has length 1 > 0
            assert(inner.len() == 1);
            res.push(inner);
            idx += 1;
        }
        res
    }
}

